38	#[derive(Debug)]
39	pub struct Iter<'a, T> {
40	    inner: Chain<slice::Iter<'a, T>, slice::Iter<'a, T>>,
41	}
42	
43	impl<T> Clone for Iter<'_, T> {
44	    fn clone(&self) -> Self {
45	        Iter {
46	            inner: self.inner.clone(),
47	        }
48	    }
49	}
