52	    type Item = &'a T;
53	    type Iter = Iter<'a, T>;
54	
55	    fn into_par_iter(self) -> Self::Iter {
56	        let (a, b) = self.as_slices();
57	        Iter {
58	            inner: a.into_par_iter().chain(b),
59	        }
60	    }
61	}
