```rust
use rayon::iter::plumbing::{Consumer, UnindexedConsumer, ProducerCallback};
use rayon::prelude::*;
use rayon::vec;

// 1. 自定义容器
#[derive(Debug, Clone, Default)]
struct MyBoxedVec<T> {
    inner: Vec<T>,
}

impl<T> From<Vec<T>> for MyBoxedVec<T> {
    fn from(v: Vec<T>) -> Self {
        MyBoxedVec { inner: v }
    }
}

// 2. 按值并行迭代器：手写「delegate_indexed_iterator!」的展开
struct IntoIter<T> {
    inner: vec::IntoIter<T>,
}

impl<T: Send> ParallelIterator for IntoIter<T> {
    type Item = T;

    fn drive_unindexed<C>(self, consumer: C) -> C::Result
    where
        C: UnindexedConsumer<Self::Item>,
    {
        self.inner.drive_unindexed(consumer)
    }

    fn opt_len(&self) -> Option<usize> {
        self.inner.opt_len()
    }
}

impl<T: Send> IndexedParallelIterator for IntoIter<T> {
    fn drive<C>(self, consumer: C) -> C::Result
    where
        C: Consumer<Self::Item>,
    {
        self.inner.drive(consumer)
    }

    fn len(&self) -> usize {
        self.inner.len()
    }

    fn with_producer<CB>(self, callback: CB) -> CB::Output
    where
        CB: ProducerCallback<Self::Item>,
    {
        self.inner.with_producer(callback)
    }
}

impl<T: Send> IntoParallelIterator for MyBoxedVec<T> {
    type Item = T;
    type Iter = IntoIter<T>;

    fn into_par_iter(self) -> Self::Iter {
        IntoIter {
            inner: self.inner.into_par_iter(),
        }
    }
}

// 3. 共享借用版：委托给切片迭代器
use rayon::slice;

struct Iter<'a, T> {
    inner: slice::Iter<'a, T>,
}

impl<'a, T: Sync> ParallelIterator for Iter<'a, T> { ... }
impl<'a, T: Sync> IndexedParallelIterator for Iter<'a, T> { ... }

impl<'a, T: Sync> IntoParallelIterator for &'a MyBoxedVec<T> {
    type Item = &'a T;
    type Iter = Iter<'a, T>;
    fn into_par_iter(self) -> Self::Iter {
        Iter { inner: self.inner.par_iter() } // &Vec → slice::Iter via delegation
    }
}
```

Wait — `self.inner.par_iter()` where inner: Vec<T> — that gives rayon::slice::Iter<'a, T>. Yes since &Vec delegates to &[T]. Need `use rayon::prelude::*` for par_iter method. Good — this also demonstrates the Vec→slice delegation from vec.rs L18-25!

